using System;using System.IO;using System.Reflection;using System.EnterpriseServices.Internal;class InstallPowerShellGac{static int Main(){string result=@"C:\amazing-compat\gac-result.txt";try{var publisher=new Publish();string text="";foreach(var file in File.ReadAllLines(@"C:\amazing-compat\gac-files.txt")){if(file.Length==0)continue;publisher.GacInstall(file);text+="INSTALLED "+Path.GetFileName(file)+"\n";}File.WriteAllText(result,text);return 0;}catch(Exception e){File.WriteAllText(result,e.ToString());return 1;}}}